#!/usr/bin/env bash
# Runs INSIDE the "tools" container (see compose.yaml). Do not run it on the host.
# KEEP=<n> deletes all but the newest n backup sets in /backups (names sort by timestamp); KEEP=0 keeps everything.
set -euo pipefail

BACKUP_DIR=${BACKUP_DIR:-/backups}
KEEP=${KEEP:-0}

if [ "$KEEP" -gt 0 ]; then
  # shellcheck disable=SC2012  # file names are generated by these scripts (letters, digits, dashes)
  (ls -1 "$BACKUP_DIR"/librenms-*-db.sql.gz 2>/dev/null || true) | sort | head -n -"$KEEP" | while read -r old; do
    echo "Pruning old backup ${old##*/}"
    rm -f "$old" "${old%-db.sql.gz}-data.tgz"
  done
fi
